from functools import wraps

def log_calls(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print(f'Calling {func.__name__} with args={args}, kwargs={kwargs}')
        result = func(*args, **kwargs)
        print(f'Returned {result}')
        return result
    return wrapper

@log_calls
def multiply(a, b):
    return a * b

