import time
from functools import wraps

def memoize(func):
    cache = {}
    @wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]
    return wrapper

@memoize
def slow_add(a, b):
    print('Computing...')
    time.sleep(1)
    return a + b

print(slow_add(3, 4))
print(slow_add(3, 4))

